def main():
    slides=json.loads(subprocess.check_output(['git','show',BASELINE+':agentic_operator_tutorial/lesson_content.json'],cwd=ROOT.parent).decode('utf-8-sig'))
    rows=[]
    for line in TEXT.strip().splitlines():
        fields=line.split('|')
        if len(fields)!=6: raise ValueError('Expected six fields: '+line[:80])
        n=int(fields[0]);rows.append(dict(number=n,title=slides[n-1]['title'],say=fields[1],visual=fields[2],question=fields[3],answer=fields[4],transition=fields[5]))
    out=ROOT/'content/presenter_script.json';out.parent.mkdir(parents=True,exist_ok=True)
    out.write_text(json.dumps(dict(baseline=BASELINE,slides=rows),ensure_ascii=False,indent=2)+'\n',encoding='utf-8')

if __name__=='__main__':main()
